using System.ComponentModel.DataAnnotations;using Microsoft.EntityFrameworkCore;using Microsoft.Extensions.Configuration;using Microsoft.Extensions.DependencyInjection;using Microsoft.Extensions.Hosting;using ZosyalMedya.Modules.Administration.Application.Configuration;using ZosyalMedya.Modules.Administration.Contracts;using ZosyalMedya.Modules.Administration.Infrastructure.Persistence;
namespace ZosyalMedya.Modules.Administration.Infrastructure;
public sealed class AdministrationOptions{public const string SectionName="Modules:Administration";[Required]public string PostgreSqlConnectionString{get;init;}=string.Empty;}
public static class DependencyInjection{public static IServiceCollection AddAdministrationModule(this IServiceCollection services,IConfiguration configuration){services.AddOptions<AdministrationOptions>().Bind(configuration.GetSection(AdministrationOptions.SectionName)).ValidateDataAnnotations().ValidateOnStart();var options=configuration.GetSection(AdministrationOptions.SectionName).Get<AdministrationOptions>()??throw new InvalidOperationException("Administration configuration missing.");services.AddDbContext<AdministrationDbContext>(x=>x.UseNpgsql(options.PostgreSqlConnectionString));services.AddScoped<IAdministrationRepository,PostgreSqlAdministrationRepository>();services.AddScoped<AdministrationModule>();services.AddScoped<IFeatureFlagService>(x=>x.GetRequiredService<AdministrationModule>());services.AddScoped<IOperationalMetrics>(x=>x.GetRequiredService<AdministrationModule>());services.AddScoped<AdministrationHandler>();services.AddHostedService<AdministrationInitializer>();return services;}}
internal sealed class AdministrationInitializer(IServiceProvider provider):IHostedService{public async Task StartAsync(CancellationToken token){await using var scope=provider.CreateAsyncScope();await scope.ServiceProvider.GetRequiredService<AdministrationDbContext>().Database.MigrateAsync(token);}public Task StopAsync(CancellationToken token)=>Task.CompletedTask;}
